const defaults={age:0,income:0,currentExpenses:0,savings:0,passive:0,stocks:0,stocksRate:0,money:0,moneyRate:0,'401k':0,'401kRate':0,home:0,car1:0,car2:0,car3:0,retire:0,expenses:0,socialAge:0,social:0,inflation:0};
const $=id=>document.getElementById(id);let mode='nominal';
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const compact=n=>n>=1e6?'$'+(n/1e6).toFixed(1)+'m':n>=1000?'$'+Math.round(n/1000)+'k':money(n);
$('investments').innerHTML=[['stocks','↗','Stocks & ETFs'],['money','≋','Money market'],['401k','▥','401(k)']].map(([k,icon,title])=>`<div class="investment-row"><span class="investment-name"><span class="asset-icon">${icon}</span>${title}</span><label class="field"><span>$</span><input id="${k}" type="number" min="0" step="1000" aria-label="${title} balance"></label><label class="field"><input id="${k}Rate" type="number" min="-50" max="50" step="0.1" aria-label="${title} annual return"><span>%</span></label></div>`).join('');
for(const[k,v]of Object.entries(defaults))$(k).value=v;
function read(){const p={};for(const k of Object.keys(defaults)){const el=$(k);let v=Number(el.value);v=Math.min(Number(el.max||1e10),Math.max(Number(el.min||0),Number.isFinite(v)?v:0));p[k]=v;}p.age=Math.round(p.age);p.retire=Math.round(p.retire);p.socialAge=Math.round(p.socialAge);return p;}
function renderEmpty(p){
 const invested=p.stocks+p.money+p['401k'],other=p.home+p.car1+p.car2+p.car3;
 $('retire-label').textContent=p.retire;$('result-age').textContent=p.retire;
 $('countdown').textContent='Start by entering your plan';
 for(const id of ['retire-balance','monthly-expense','monthly-passive','affordable'])$(id).textContent=money(0);
 $('earliest').textContent='—';$('wealth').textContent=money(invested+other);$('invested').textContent=money(invested);$('other').textContent=money(other);$('wealth-ratio').style.width=(invested+other?invested/(invested+other)*100:0)+'%';
 $('runout-title').textContent='Your next chapter starts with a plan';$('runout-text').textContent=p.social>0&&p.socialAge<18?'Enter your Social Security starting age to complete your projection.':'Enter your age and retirement age to calculate your projection.';
 $('validation').textContent=p.age===0&&p.retire===0?'':p.age<18?'Enter your current age (18 or older).':p.retire<p.age?'Choose a retirement age at or after your current age.':'Enter a Social Security starting age (18 or older).';
 renderPendingCharts(p);
 $('mix-subtitle').textContent='Annual income at retirement';$('yearly-rows').innerHTML='<tr><td colspan="8">Enter your plan to see the year-by-year projection.</td></tr>';
}
function renderPendingCharts(p){
 const grid=[48,106,164,222].map(y=>`<line x1="68" y1="${y}" x2="374" y2="${y}" stroke="#e4eadc"/><text x="58" y="${y+5}" text-anchor="end" fill="#738369" font-size="16">$0</text>`).join('');
 $('journey-chart').innerHTML=`<svg viewBox="0 0 400 260" role="img" aria-label="Investment balance chart awaiting your plan"><title>Investment balance chart — enter your ages to calculate a projection</title>${grid}<line x1="68" y1="222" x2="374" y2="222" stroke="#547d4f" stroke-width="3"/><circle cx="68" cy="222" r="5" fill="#547d4f"/><text x="68" y="250" fill="#738369" font-size="16">Today</text><text x="374" y="250" text-anchor="end" fill="#738369" font-size="16">Future</text><text x="221" y="120" text-anchor="middle" fill="#647659" font-size="16">Enter your ages to project</text><text x="221" y="146" text-anchor="middle" fill="#647659" font-size="16">your investment balance</text></svg>`;
 income(p,{expense:0,passive:0,social:0,factor:1});
 $('milestone-chart').innerHTML=`<div class="milestone-bars pending-milestones" role="img" aria-label="Retirement milestones awaiting a completed plan">${[[p.age,42],[p.retire,76],[0,104]].map(([age,height])=>`<div class="milestone-column"><strong>${age>0?age:'—'}</strong><div class="column" style="height:${height}px"></div></div>`).join('')}</div><div class="milestone-labels"><span>Your age<br>today</span><span>Selected<br>retirement</span><span>Funding<br>horizon</span></div><p class="note">Complete your plan to calculate the funding horizon.</p>`;
}
function render(){const p=read();
const available=p.income+p.passive-p.currentExpenses;
$('cash-flow-label').textContent=available<0?'Annual cash-flow shortfall':'Available to invest / year';
$('cash-flow-value').textContent=money(Math.abs(available));
$('cash-flow-value').classList.toggle('shortfall',available<0);
$('cash-flow-warning').textContent=available<0?'Your current living expenses exceed your take-home and passive income.':p.savings>available?'Your annual investment amount exceeds the income left after living expenses. Check whether other funding covers the difference.':'';
if(p.age<18||p.retire<p.age||p.retire===0||(p.social>0&&p.socialAge<18)){renderEmpty(p);return;}$('retire').min=0;$('retire').max=Math.max(85,p.age);$('retire').value=p.retire;$('range-min').textContent=0;const m=FreedomModel.project(p);const r=m.rows.find(r=>r.age===p.retire);const invested=p.stocks+p.money+p['401k'];const other=p.home+p.car1+p.car2+p.car3;
$('retire-label').textContent=p.retire;$('result-age').textContent=p.retire;$('countdown').textContent=p.retire===p.age?'Your next chapter starts today':`${p.retire-p.age} years to your next chapter`;$('retire-balance').textContent=money(m.retirementBalance);$('monthly-expense').textContent=money(r.expense/12);$('monthly-passive').textContent=money(r.passive/12);$('wealth').textContent=money(invested+other);$('invested').textContent=money(invested);$('other').textContent=money(other);$('wealth-ratio').style.width=(invested+other?invested/(invested+other)*100:0)+'%';
$('runout-title').textContent=m.runout===null?'Your money lasts through age 100':`Investments run short at age ${m.runout}`;$('runout-text').textContent=m.runout===null?`Your spending is covered through our projection, with ${money(m.rows.at(-1).end)} remaining at 100.`:`Your planned spending exceeds available income and savings ${m.runout-p.retire} years into retirement.`;
$('validation').textContent=p.retire<59.5&&p['401k']>0?'This model includes your 401(k). Early access restrictions and penalties are not modeled.':'';
let earliest=null;for(let a=p.age;a<=99;a++){if(FreedomModel.project({...p,retire:a}).runout===null){earliest=a;break;}}
$('earliest').textContent=earliest===null?'Beyond 99':`Age ${earliest}`;
let low=0,high=Math.max(1000000,p.expenses*2);while(FreedomModel.project({...p,expenses:high}).runout===null&&high<1e10)high*=2;
for(let i=0;i<35;i++){const mid=(low+high)/2;if(FreedomModel.project({...p,expenses:mid}).runout===null)low=mid;else high=mid;}
$('affordable').textContent=money(low/12);
$('yearly-rows').innerHTML=m.rows.filter(row=>row.age>=p.retire).map(row=>`<tr><td>${row.age}</td><td>${money(row.start)}</td><td>${money(row.passive)}</td><td>${money(row.social)}</td><td>${money(row.expense)}</td><td>${money(row.withdrawal)}</td><td class="${row.shortfall>0?'shortfall':''}">${money(row.shortfall)}</td><td>${money(row.end)}</td></tr>`).join('');
journey(p,m);income(p,r);milestones(p,m);
}
function journey(p,m){const W=400,H=260,L=68,R=26,T=42,B=38;const values=m.rows.map(r=>r.start/(mode==='real'?r.factor:1));const max=Math.max(1,...values)*1.12;const x=a=>L+(a-p.age)/(100-p.age)*(W-L-R);const y=v=>H-B-v/max*(H-T-B);const points=m.rows.map((r,i)=>`${x(r.age)},${y(values[i])}`).join(' ');const area=`${L},${H-B} ${points} ${W-R},${H-B}`;let grid='';for(let i=0;i<4;i++){const val=max*i/3,yy=y(val);grid+=`<line x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}" stroke="#edf0e6"/><text x="${L-8}" y="${yy+5}" text-anchor="end" fill="#a0aa94" font-size="16">${compact(val)}</text>`;}const ticks=[p.age,Math.round(p.age+(100-p.age)/3),Math.round(p.age+2*(100-p.age)/3),100];grid+=ticks.map(a=>`<text x="${x(a)}" y="${H-10}" text-anchor="middle" fill="#9aa58e" font-size="16">${a}</text>`).join('');$('journey-chart').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Projected investment balance from age ${p.age} to 100"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a7c58a" stop-opacity=".35"/><stop offset="1" stop-color="#c4d7a7" stop-opacity=".03"/></linearGradient></defs>${grid}<polygon points="${area}" fill="url(#area)"/><polyline points="${points}" transform="translate(0 4)" fill="none" stroke="#c7d5b8" stroke-width="4" opacity=".5"/><polyline points="${points}" fill="none" stroke="#547d4f" stroke-width="2.5" stroke-linejoin="round"/><line x1="${x(p.retire)}" y1="${T}" x2="${x(p.retire)}" y2="${H-B}" stroke="#9aad81" stroke-dasharray="3 4"/><text x="${Math.min(W-80,x(p.retire)+8)}" y="24" font-size="16" fill="#7b9067">Age ${p.retire}</text></svg>`;}
function income(p,r){const scale=mode==='real'?r.factor:1;const items=[{label:'Investment withdrawals',val:Math.max(0,r.expense-r.passive-r.social),color:'#547653',cls:'green'},{label:'Passive income',val:r.passive,color:'#a9c585',cls:'pale'},{label:'Social Security',val:r.social,color:'#d2b879',cls:'gold'}];const sum=items.reduce((s,i)=>s+i.val,0);let offset=0;const slices=items.map(i=>{const len=sum?i.val/sum*100:0;const s=`<circle cx="140" cy="76" r="55" fill="none" stroke="${i.color}" stroke-width="26" pathLength="100" stroke-dasharray="${len} ${100-len}" stroke-dashoffset="${-offset}" transform="rotate(-90 140 76)"/>`;offset+=len;return s;}).join('');$('income-chart').innerHTML=`<svg viewBox="0 0 280 155" role="img" aria-label="Annual retirement income sources"><ellipse cx="140" cy="87" rx="68" ry="66" fill="#dce3d2"/><circle cx="140" cy="76" r="55" fill="white" stroke="#eef1e7" stroke-width="26"/>${slices}<text x="140" y="76" text-anchor="middle" fill="#405d3b" font-family="Manrope,sans-serif" font-size="26" font-weight="600">${compact(sum/scale)}</text><text x="140" y="96" text-anchor="middle" fill="#98a38b" font-size="12">PER YEAR</text></svg>`;$('income-legend').innerHTML=items.map(i=>`<div class="income-legend-item"><span><i class="${i.cls}"></i>${i.label}</span><b>${money(i.val/scale)}</b></div>`).join('');$('mix-subtitle').textContent=`Annual income needed at age ${p.retire}`;}
function milestones(p,m){const end=m.runout??100;$('milestone-chart').innerHTML=`<div class="milestone-bars">${[[p.age,42],[p.retire,76],[end,104]].map(([a,h])=>`<div class="milestone-column"><strong>${a}${a===100&&m.runout===null?'+':''}</strong><div class="column" style="height:${h}px"></div></div>`).join('')}</div><div class="milestone-labels"><span>Your age<br>today</span><span>Selected<br>retirement</span><span>${m.runout===null?'Funded<br>through':'Savings<br>run short'}</span></div><p class="note">Ages shown under your current assumptions.</p>`;}
for(const k of Object.keys(defaults))$(k).addEventListener('input',render);$('reset').addEventListener('click',()=>{for(const[k,v]of Object.entries(defaults))$(k).value=v;render();});document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(t=>t.classList.toggle('selected',t===b));render();}));render();
